// Screen registry: every legacy screen code → component, roles, tab, main, fallbackBack.
// All data comes from real API endpoints; labels are bilingual UI text, never data records.
import { registerScreen } from './stores.jsx';
import { AUTH_COMPONENTS } from '../modules/auth/AuthScreens.jsx';
import { OWNER_COMPONENTS } from '../modules/owner/OwnerScreens.jsx';
import { MECHANIC_COMPONENTS } from '../modules/mechanic/MechanicScreens.jsx';
import { CAPTAIN_COMPONENTS } from '../modules/captain/CaptainScreens.jsx';
import { CENTER_COMPONENTS } from '../modules/center/CenterScreens.jsx';
import { ADMIN_COMPONENTS } from '../modules/admin/AdminScreens.jsx';
import { SHARED_COMPONENTS } from '../modules/shared/SharedScreens.jsx';

const ALL_COMPONENTS = {
  ...AUTH_COMPONENTS,
  ...OWNER_COMPONENTS,
  ...MECHANIC_COMPONENTS,
  ...CAPTAIN_COMPONENTS,
  ...CENTER_COMPONENTS,
  ...ADMIN_COMPONENTS,
  ...SHARED_COMPONENTS,
};

const PUB = ['guest', 'CarOwner', 'Mechanic', 'TowCaptain', 'ServiceCenter', 'Admin'];
const ALL = ['CarOwner', 'Mechanic', 'TowCaptain', 'ServiceCenter', 'Admin'];
const OWNER = ['CarOwner'];
const MECH = ['Mechanic'];
const CAP = ['TowCaptain'];
const CENTER = ['ServiceCenter'];
const ADMIN = ['Admin'];
const PROV = ['Mechanic', 'TowCaptain', 'ServiceCenter'];

const S = (code, module, en, ar, o = {}) => registerScreen(code, {
  code, module,
  label: `${code} · ${en}`, labelAr: `${code} · ${ar}`,
  roles: o.roles || ALL, main: !!o.main, tab: o.tab || null,
  fallbackBack: o.back === undefined ? null : o.back,
  Component: ALL_COMPONENTS[code] || o.Component || null,
  view: o.view || { type: 'info', titleEn: en, titleAr: ar }
});

const info = (en, ar, bodyEn, bodyAr, actions = []) => ({ type: 'info', titleEn: en, titleAr: ar, headingEn: en, headingAr: ar, bodyEn, bodyAr, actions });
const list = (en, ar, path, extra = {}) => ({ type: 'list', titleEn: en, titleAr: ar, path, ...extra });
const dash = (en, ar, path, extra = {}) => ({ type: 'dashboard', titleEn: en, titleAr: ar, path, ...extra });
const detail = (en, ar, path, extra = {}) => ({ type: 'detail', titleEn: en, titleAr: ar, path, ...extra });
const form = (en, ar, path, fields, extra = {}) => ({ type: 'form', titleEn: en, titleAr: ar, path, fields, ...extra });
const map = (en, ar, path, extra = {}) => ({ type: 'mapStatus', titleEn: en, titleAr: ar, path, ...extra });

